const BUILD_SLOTS={nba:['Finishing','Speed','Bounce','Passing','Defense','Shooting','Handles','IQ','Height'],nfl:['Speed','Strength','Throwing','Catching','Route Running','Tackling','Awareness','Agility','Height'],soccer:['Pace','Shooting','Passing','Dribbling','Defending','Physical','Vision','Stamina','Height'],mlb:['Contact','Power','Plate Vision','Speed','Arm','Fielding','Pitching','Control','Height']};function draftSlots(sport=app.sport,mode='squad'){return mode==='build'?BUILD_SLOTS[sport]:LEAGUES[sport].slots}
function eligibleDraft(d){let used=new Set(d.picks.map(p=>p.id));let pool=ALL[d.sport].filter(p=>!used.has(p.id));const fits=p=>d.sport==='nba'||d.mode==='build'||(d.sport==='nfl'&&d.slots[d.round]==='FLEX'?(p.pos||[]).some(v=>['RB','WR','TE'].includes(v)):(p.pos||[]).includes(d.slots[d.round]));if(d.poolEra==='current'){const recent=pool.filter(p=>p.season>=2018).filter(fits);if(recent.length)return recent;}return pool.filter(fits)}
function rollDraft(d,key='init'){
 const options=eligibleDraft(d);if(!options.length)return;
 let random=rng(hash([d.seed,d.round,d.rollIndex,key].join(':')));
 let cat=d.slots[d.round]||'FINAL';
 if(d.sport==='nba'&&d.picks.length===0&&key==='init')d.categories=shuffle(d.mode==='build'?BUILD_SLOTS.nba:LEAGUES.nba.slots,d.seed);
 if(d.sport==='nba')cat=d.categories?.[d.round]||cat;
 d.category=cat;
 const choose=(a)=>a[Math.floor(random()*a.length)]||a[0];
 let teams=[...new Set(options.map(p=>p.team))];
 if(d.lockedTeam&&teams.includes(d.lockedTeam))d.team=d.lockedTeam;
 else d.team=choose(teams);
 let teamPool=options.filter(p=>p.team===d.team);
 let era=(choose(teamPool)||choose(options)).season;
 d.era=Math.floor(era/10)*10;
 d.boardSeed=[d.seed,d.round,d.rollIndex].join(':');
 d.rerolls={team:1,era:1,stat:1};
 d.revealed=false;
}
function newDraft(mode){if(mode==='coach'){setPage('coach');return}let m=['classic','blind','daily','weekly','auction','playoff','team','season','build','current','alltime'].includes(mode)?mode:'classic';if(m==='daily'&&app.daily[app.sport+':'+today()]){notify('Daily already completed on this device');return;}if(m==='weekly'&&app.weekly[app.sport+':'+weekKey()]){notify('Weekly challenge already completed on this device');return;}
 let seed=m==='daily'?hash(today()+':'+app.sport+':daily'):m==='weekly'?hash(weekKey()+':'+app.sport+':weekly'):Math.floor(Math.random()*1e9);
 let d={sport:app.sport,mode:m,seed,round:0,slots:[...draftSlots(app.sport,m)],picks:[],started:Date.now(),rollIndex:0,budget:app.sport==='nfl'?100:170,lockedTeam:null,categories:null,done:false,rerolls:{team:1,era:1,stat:1},boardSeed:'',current:null,poolEra:m==='current'?'current':'alltime'};
 if(m==='team')d.lockedTeam=PRO_TEAMS[app.sport][0];
 rollDraft(d);app.draft=d;setPage('draft');}
function rerollDraft(type){const d=app.draft;if(!d||d.done||!d.rerolls[type])return;d.rerolls[type]--;d.rollIndex++;
 const items=eligibleDraft(d);if(type==='team'){const teams=[...new Set(items.map(p=>p.team))].filter(t=>t!==d.team);if(teams.length)d.team=pick(teams,d.seed+':t:'+d.rollIndex);}
 if(type==='era'){const eras=[...new Set(items.filter(p=>p.team===d.team).map(p=>Math.floor(p.season/10)*10))].filter(e=>e!==d.era);if(eras.length)d.era=pick(eras,d.seed+':e:'+d.rollIndex)}
 if(type==='stat'&&d.sport==='nba'){let remaining=LEAGUES.nba.slots.filter(x=>!d.picks.some(p=>p.slot===x)&&x!==d.category);if(remaining.length){let next=pick(remaining,d.seed+':stat:'+d.rollIndex),old=d.categories[d.round],swap=d.categories.indexOf(next,d.round+1);if(swap>=0)d.categories[swap]=old;d.categories[d.round]=next;d.category=next;}}
 if(type==='stat'&&d.sport!=='nba'){notify('Position slots are fixed in this sport.');return;}
 persist();render();}
