function syncCoachUI(){const s=coach;if(!s||app.page!=='coach')return;for(const [id,v] of [['simHomeScore',s.home],['simAwayScore',s.away],['simClock',coachTime()],['simPoss',s.sport==='mlb'?`${s.half} INNING`:s.possession==='home'?'YOUR POSSESSION':'DEFENDING']]){let el=$('#'+id);if(el)el.textContent=v;}
 const feed=$('#coachFeed');if(feed)feed.innerHTML=s.feed.slice(0,13).map(x=>`<div>${h(x)}</div>`).join('');const row=$('#coachLineup');if(row)row.innerHTML=s.homeActors.slice(0,12).map(p=>`<div class="lineup-bubble"><span>${h(short(p.name))} <small>${h(p.pos)}</small></span><span class="energy"><i style="width:${p.energy}%"></i></span></div>`).join('');}
const C_W=1000,C_H=630;
function simLine(ctx,points,color='#ffffffa9',width=2){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x*C_W,y*C_H):ctx.moveTo(x*C_W,y*C_H));ctx.stroke();}
function rectLine(ctx,x,y,w,he,color='#ffffff8c',lw=2){ctx.strokeStyle=color;ctx.lineWidth=lw;ctx.strokeRect(x*C_W,y*C_H,w*C_W,he*C_H)}
function drawPitch(ctx,sport){ctx.fillStyle=sport==='nba'?'#b68b59':sport==='nfl'?'#215e3c':sport==='soccer'?'#24734b':'#386b48';ctx.fillRect(0,0,C_W,C_H);
 if(sport==='nba'){
  for(let i=0;i<14;i++){ctx.fillStyle=i%2?'#ffffff0a':'#422d0a18';ctx.fillRect(i*C_W/14,0,C_W/14,C_H)}
  rectLine(ctx,.025,.035,.95,.93,'#fff6e9',3);simLine(ctx,[[.5,.035],[.5,.965]],'#fff9e9',3);ctx.strokeStyle='#fff9e9';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(.5*C_W,.5*C_H,72,72,0,0,Math.PI*2);ctx.stroke();
  rectLine(ctx,.027,.29,.145,.42,'#fff9e9',3);rectLine(ctx,.828,.29,.145,.42,'#fff9e9',3);
  for(let flip of [false,true]){let x=(flip?.93:.07)*C_W;ctx.beginPath();ctx.arc(x,C_H*.5,21,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.arc(x,C_H*.5,270,-Math.PI*.48,Math.PI*.48,!flip);ctx.stroke();ctx.beginPath();ctx.ellipse(x,C_H*.5,190,205,0,flip?Math.PI*.4:-Math.PI*.4,flip?Math.PI*1.6:Math.PI*.4,flip);ctx.stroke();}
 }else if(sport==='soccer'){
  for(let i=0;i<12;i++){ctx.fillStyle=i%2?'#ffffff09':'#0000000c';ctx.fillRect(i*C_W/12,0,C_W/12,C_H)}rectLine(ctx,.028,.04,.944,.92,'#f1fff3',3);simLine(ctx,[[.5,.04],[.5,.96]],'#fff',3);ctx.strokeStyle='#f5fff0';ctx.lineWidth=3;ctx.beginPath();ctx.arc(.5*C_W,.5*C_H,85,0,Math.PI*2);ctx.stroke();rectLine(ctx,.028,.21,.15,.58,'#f1fff3',2.5);rectLine(ctx,.822,.21,.15,.58,'#f1fff3',2.5);rectLine(ctx,.028,.35,.068,.30,'#f1fff3',2);rectLine(ctx,.904,.35,.068,.30,'#f1fff3',2);ctx.beginPath();ctx.arc(.115*C_W,.5*C_H,5,0,Math.PI*2);ctx.arc(.885*C_W,.5*C_H,5,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();
 }else if(sport==='nfl'){
  for(let i=0;i<=10;i++){let x=(.04+i*.092)*C_W;ctx.strokeStyle='#ffffff9a';ctx.lineWidth=i%5===0?3:1.3;ctx.beginPath();ctx.moveTo(x,.09*C_H);ctx.lineTo(x,.91*C_H);ctx.stroke();if(i<10){ctx.fillStyle='#ffffff80';ctx.font='700 22px Space Mono,monospace';ctx.textAlign='center';ctx.fillText(String(i<5?10*(i+1):10*(10-i)),x+46,.17*C_H);}}
  ctx.fillStyle='#1a4632';ctx.fillRect(0,0,.055*C_W,C_H);ctx.fillRect(.945*C_W,0,.055*C_W,C_H);rectLine(ctx,.055,.09,.89,.82,'#f1fff3',3);ctx.textAlign='center';ctx.font='800 38px Georgia';ctx.save();ctx.translate(.025*C_W,.5*C_H);ctx.rotate(-Math.PI/2);ctx.fillStyle='#e8f2df55';ctx.fillText('END ZONE',0,0);ctx.restore();
 }else{
  ctx.fillStyle='#aa7844';ctx.beginPath();ctx.moveTo(.50*C_W,.17*C_H);ctx.lineTo(.84*C_W,.5*C_H);ctx.lineTo(.50*C_W,.88*C_H);ctx.lineTo(.17*C_W,.5*C_H);ctx.closePath();ctx.fill();ctx.strokeStyle='#f5f0dd';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#3d814a';ctx.beginPath();ctx.arc(.50*C_W,.50*C_H,92,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#f0e7d4';ctx.stroke();ctx.fillStyle='#f6e9d2';for(let [x,y] of [[.5,.17],[.84,.5],[.5,.88],[.17,.5]]){ctx.fillRect(x*C_W-6,y*C_H-6,12,12)}ctx.beginPath();ctx.arc(.5*C_W,.86*C_H,38,Math.PI,0);ctx.stroke();
 }
 // broad arena/broadcast vignette rather than pixel textures
 let shade=ctx.createLinearGradient(0,0,0,C_H);shade.addColorStop(0,'#030b0a20');shade.addColorStop(.5,'#030b0a00');shade.addColorStop(1,'#030b0a30');ctx.fillStyle=shade;ctx.fillRect(0,0,C_W,C_H);
}
function drawCircle(ctx,p,team,t){let x=p.x*C_W,y=p.y*C_H,shift=Math.sin(t*1.55+p.number*1.81)*6;let breathing=Math.cos(t*1.3+p.number)*1.5;let extra=coach?.active?(team===0?Math.sin(t+p.number)*Math.min(13,coach.progress*14):Math.sin(t+p.number+1)*9):0;let dy=breathing+extra;let r=team===0?21:19;
 ctx.shadowColor='#07130b6a';ctx.shadowBlur=10;ctx.shadowOffsetY=2;ctx.beginPath();ctx.arc(x+shift,y+dy,r,0,Math.PI*2);ctx.fillStyle=team===0?'#f2cb60':'#233044';ctx.fill();ctx.shadowBlur=0;ctx.shadowOffsetY=0;ctx.lineWidth=team===0?4:3;ctx.strokeStyle=team===0?'#fff7df':'#f6f7eb';ctx.stroke();
 ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='700 14px DM Sans,Arial';ctx.fillStyle=team===0?'#17221b':'#f1f3f5';ctx.fillText((p.pos||'P').slice(0,3),x+shift,y+dy);ctx.fillStyle='#ffffff';ctx.font='700 15px DM Sans,Arial';ctx.strokeStyle='#05120f';ctx.lineWidth=4;ctx.strokeText(short(p.name),x+shift,y+dy+r+19);ctx.fillText(short(p.name),x+shift,y+dy+r+19);
 return{x:x+shift,y:y+dy};
}
function drawCoachCanvas(t){let s=coach,can=$('#simCanvas');if(!s||!can||app.page!=='coach')return;const ctx=can.getContext('2d');if(!ctx)return;let w=can.getBoundingClientRect().width||900,hg=can.getBoundingClientRect().height||560,device=Math.min(2,window.devicePixelRatio||1),width=Math.max(1,Math.floor(w*device)),height=Math.max(1,Math.floor(hg*device));if(can.width!==width||can.height!==height){can.width=width;can.height=height;}ctx.setTransform(width/C_W,0,0,height/C_H,0,0);drawPitch(ctx,s.sport);
 // tactically directed movement trails and play arrows
 ctx.save();ctx.setLineDash([9,8]);ctx.lineWidth=4;ctx.strokeStyle='#ffef86a6';let target=s.nextPlay==='Pick & Roll'?.78:s.nextPlay==='Fast Break'?.94:.64;ctx.beginPath();ctx.moveTo(.27*C_W,.44*C_H);ctx.quadraticCurveTo(.50*C_W,.23*C_H,target*C_W,.47*C_H);ctx.stroke();ctx.restore();
 if(s.customPath.length>=2){ctx.strokeStyle='#ffe9a5';ctx.lineWidth=5;ctx.setLineDash([8,6]);ctx.beginPath();s.customPath.forEach((p,i)=>i?ctx.lineTo(p[0]*C_W,p[1]*C_H):ctx.moveTo(p[0]*C_W,p[1]*C_H));ctx.stroke();ctx.setLineDash([]);}
 let circlePoints,awayPts;if(s.sport==='mlb'){let field=s.possession==='away'?s.homeActors:s.awayActors,batter=s.possession==='away'?s.awayActors[0]:s.homeActors[0],fieldHome=s.possession==='away';circlePoints=field.map(p=>drawCircle(ctx,p,fieldHome?0:1,t));let batting={...batter,x:.50,y:.91,pos:'BAT'};awayPts=[drawCircle(ctx,batting,fieldHome?1:0,t)];}else{circlePoints=s.homeActors.map(p=>drawCircle(ctx,p,0,t));awayPts=s.awayActors.map(p=>drawCircle(ctx,p,1,t));}
 // ball follows a passing path and changes possession. Render in front of players.
 let pts=s.sport==='mlb'?[circlePoints[0],...awayPts]:s.possession==='home'?circlePoints:awayPts;let from=pts[(s.phase+s.eventCount)%pts.length],to=pts[(s.phase+s.eventCount+2)%pts.length],u=(s.progress%1),bx=from.x+(to.x-from.x)*Math.min(1,u*1.23),by=from.y+(to.y-from.y)*Math.min(1,u*1.23);if(s.sport==='mlb'){bx=(.51+Math.cos(u*Math.PI*1.7)*.05)*C_W;by=(.51+Math.sin(u*Math.PI*1.7)*.20)*C_H;}
 ctx.shadowBlur=13;ctx.shadowColor='#2a0a00aa';ctx.beginPath();ctx.arc(bx,by,s.sport==='nfl'?9:s.sport==='soccer'?11:11,0,Math.PI*2);ctx.fillStyle=s.sport==='soccer'||s.sport==='mlb'?'#f9f7ea':'#df793a';ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#231b0d';ctx.lineWidth=2;ctx.stroke();ctx.beginPath();ctx.moveTo(bx-5,by-4);ctx.lineTo(bx+5,by+4);ctx.moveTo(bx+5,by-4);ctx.lineTo(bx-5,by+4);ctx.strokeStyle=s.sport==='soccer'?'#24352e':'#8b361c';ctx.stroke();
 if(s.drawing){ctx.fillStyle='#fff7da';ctx.font='700 16px Space Mono';ctx.fillText('DRAW ROUTE · CLICK TWO OR MORE POINTS',C_W*.5,45)}
}
function animateCoach(t){if(coach&&app.page==='coach'){
 let dt=lastFrame?Math.min(.08,(t-lastFrame)/1000):0;lastFrame=t;
 if(coach.active&&!coach.paused){coach.elapsed+=dt*coach.speed;coach.progress=clamp(coach.elapsed/2.9,0,1);if(coach.elapsed>=2.9){coach.elapsed=0;coachSimPlay();}}
 drawCoachCanvas(t/1000);
 }else lastFrame=0;
 coachRAF=requestAnimationFrame(animateCoach)}
function coachPause(){if(!coach||coach.finished)return;coach.paused=!coach.paused;coach.elapsed=0;render()}
function coachStep(){if(!coach||coach.finished)return;coachSimPlay();coach.elapsed=0;render()}
function coachSimFinal(){if(!coach||coach.finished)return;for(let i=0;i<220&&coach.active;i++)coachSimPlay();render()}
function coachTimeout(){let s=coach;if(!s||s.timeouts<=0)return;s.timeouts--;s.paused=true;s.homeActors.forEach(x=>x.energy=clamp(x.energy+7,0,100));coachLog('TIMEOUT: Team regroups and recovers some energy.');render()}
const gridRows={
 nba:[{name:'GUARDS',test:p=>p.pos.some(x=>['PG','SG'].includes(x))},{name:'WINGS',test:p=>p.pos.some(x=>['SF','PF'].includes(x))},{name:'CENTERS',test:p=>p.pos.includes('C')}],
 nfl:[{name:'QUARTERBACK',test:p=>p.pos.includes('QB')},{name:'SKILL OFFENSE',test:p=>p.pos.some(x=>['RB','WR','TE'].includes(x))},{name:'DEFENSE',test:p=>p.pos.some(x=>['CB','LB','EDGE','FS','SS'].includes(x))}],
 soccer:[{name:'DEFENDER',test:p=>p.pos.some(x=>['GK','RB','CB','LB','RWB','LWB'].includes(x))},{name:'MIDFIELDER',test:p=>p.pos.some(x=>['CM','CDM','CAM'].includes(x))},{name:'FORWARD',test:p=>p.pos.some(x=>['ST','RW','LW'].includes(x))}],
 mlb:[{name:'PITCHER',test:p=>p.pos.includes('P')},{name:'INFIELDER',test:p=>p.pos.some(x=>['1B','2B','3B','SS','C'].includes(x))},{name:'HITTER',test:p=>p.pos.some(x=>['LF','CF','RF','DH'].includes(x))}]
};
const gridCols={
 nba:[{name:'BEFORE 2010',test:p=>p.season<2010},{name:'2010 & LATER',test:p=>p.season>=2010},{name:'90+ RATING',test:p=>p.rating>=90}],
 nfl:[{name:'BEFORE 2010',test:p=>p.season<2010},{name:'2010 & LATER',test:p=>p.season>=2010},{name:'90+ RATING',test:p=>p.rating>=90}],
 soccer:[{name:'BEFORE 2015',test:p=>p.season<2015},{name:'2015 & LATER',test:p=>p.season>=2015},{name:'90+ RATING',test:p=>p.rating>=90}],
 mlb:[{name:'BEFORE 2000',test:p=>p.season<2000},{name:'2000 & LATER',test:p=>p.season>=2000},{name:'90+ RATING',test:p=>p.rating>=90}]
};
let gridSelected=0;
function gridState(){if(!app.grid||app.grid.sport!==app.sport||app.grid.date!==today())app.grid={sport:app.sport,date:today(),cells:Array.from({length:9},()=>null),tries:0,solved:0,used:[],history:[]};return app.grid}
function gridGuess(input){let g=gridState(),idx=gridSelected,p=ALL[app.sport].find(x=>x.name.toLowerCase()===input.trim().toLowerCase());if(g.tries>=9){notify('Nine guesses used');return;}if(g.cells[idx]?.success){notify('Cell already solved');return;}const row=gridRows[app.sport][Math.floor(idx/3)],col=gridCols[app.sport][idx%3];let success=!!p&&!g.used.includes(p.name)&&row.test(p)&&col.test(p);
 g.tries++;g.cells[idx]={guess:input.trim()||'PASS',success};g.history.push(`${row.name} + ${col.name}: ${input||'PASS'} ${success?'✓':'✕'}`);if(success){g.solved++;g.used.push(p.name)}if(g.solved===9)app.medals.grid=true;persist();render();notify(success?'Correct player!':p?'Not a match for this square':'Player not in curated database');}
function renderGrid(){let g=gridState();const rows=gridRows[app.sport],cols=gridCols[app.sport];return `<div class="page-title"><div><div class="eyebrow">DAILY PUZZLE / ${today()}</div><h1>Nine squares.</h1><p>Name a real historical athlete who satisfies both the row and column. Each name can be used once.</p></div><span class="pill">${g.solved} / 9 COMPLETED · ${9-g.tries} GUESSES LEFT</span></div><div class="two-col"><div class="pane"><div class="grid-game"><div class="grid-cell grid-head">ERA / ROLE</div>${cols.map(x=>`<div class="grid-cell grid-head">${h(x.name)}</div>`).join('')}${rows.map((row,r)=>`<div class="grid-cell grid-head">${h(row.name)}</div>${cols.map((col,c)=>{let idx=r*3+c,x=g.cells[idx];return `<div class="grid-cell ${x?.success?'ok':x?'bad':''} ${idx===gridSelected?'current':''}"><button data-grid-cell="${idx}" ${x?.success||g.tries>=9?'disabled':''}>${x?`${h(x.guess)} ${x.success?'✓':'✕'}`:'+ PICK'}</button></div>`}).join('')}`).join('')}</div><p class="mini-note">Curated players only. Historical player-season associations are limited. The grid is saved locally.</p></div><div class="pane"><div class="eyebrow">ENTER YOUR ANSWER</div><h3>${h(rows[Math.floor(gridSelected/3)].name)} + ${h(cols[gridSelected%3].name)}</h3><label class="field">PLAYER NAME<input id="gridInput" list="gridPlayers" placeholder="Type exact player name" ${g.tries>=9?'disabled':''}></label><datalist id="gridPlayers">${[...new Set(ALL[app.sport].map(p=>p.name))].sort().map(x=>`<option value="${h(x)}"></option>`).join('')}</datalist><div class="action-row"><button class="btn primary" id="submitGrid" ${g.tries>=9?'disabled':''}>SUBMIT GUESS</button><button class="btn" id="gridHelp">SEE RULES</button></div><div class="divline"></div><div class="eyebrow">GUESSES</div>${g.history.length?g.history.slice().reverse().map(v=>`<div class="summary-stat"><span>${h(v)}</span></div>`).join(''):'<p class="mini-note">Your grid is empty. Nine attempts, no duplicates.</p>'}</div></div>`}
let profileTab='overview';
const badges=[{id:'firstPick',icon:'🏁',name:'First Draft',desc:'Complete any fantasy draft.'},{id:'ninety',icon:'⭐',name:'Elite Builder',desc:'Score 90 or better.'},{id:'perfect',icon:'💯',name:'The 95 Club',desc:'Score 95 or higher.'},{id:'brave',icon:'🎭',name:'Blind Faith',desc:'Complete a blind draft.'},{id:'auction',icon:'💰',name:'Budget Architect',desc:'Complete an auction draft.'},{id:'coach',icon:'📋',name:'Sideline General',desc:'Finish a coached match.'},{id:'veteran',icon:'🏅',name:'Career Veteran',desc:'Complete a professional season.'},{id:'champion',icon:'🏆',name:'Champion',desc:'Win a season title.'},{id:'grid',icon:'🧩',name:'Grid Master',desc:'Solve nine squares in one day.'}];
function topScore(records){let r=records.slice().sort((a,b)=>b.score-a.score)[0];return r?r.score:'—'}
function renderProfile(){const hist=getGames(),career=owned(),sum=hist.reduce((a,x)=>a+x.score,0),days=hist.filter(x=>x.mode==='daily'),last=hist[0],records=hist.slice().sort((a,b)=>b.score-a.score);let tabs=[['overview','OVERVIEW'],['leaderboards','LEADERBOARDS'],['badges','BADGES'],['hall','HALL & RECORDS'],['league','LOCAL LEAGUE'],['past','PAST DAILIES'],['settings','SETTINGS']];let body='';
 if(profileTab==='overview')body=`<div class="three-col">${[statTile(hist.length,'DRAFTS FINISHED'),statTile(topScore(hist),'BEST FANTASY SCORE'),statTile((hist.length?Math.round(sum/hist.length*10)/10:0),'AVERAGE SCORE')].map(x=>`<div class="pane">${x}</div>`).join('')}</div><div class="two-col" style="margin-top:14px"><div class="pane"><h3>Recent drafts.</h3>${hist.length?hist.slice(0,10).map(r=>`<div class="summary-stat"><span><b>${h(r.mode.toUpperCase())}</b> · ${r.date}</span><strong>${r.score}</strong></div>`).join(''):'<div class="empty">No draft history yet.</div>'}</div><div class="pane"><h3>Your pro career.</h3>${career?`<p>${h(career.player.name)} · ${h(career.team)}</p><div class="two-col">${statTile(career.season,'SEASON')}${statTile(career.rings,'TITLES')}</div><button class="btn sm green" data-page="career">GO TO CAREER →</button>`:'<div class="empty">No professional career saved yet.</div>'}<div class="divline"></div><button class="btn sm" id="editUsername">CHANGE PROFILE NAME</button></div></div>`;
 else if(profileTab==='leaderboards')body=`<div class="two-col"><div class="pane"><h3>Best on this device.</h3><table class="history-table"><thead><tr><th>RANK</th><th>MODE</th><th>DATE</th><th>SCORE</th></tr></thead><tbody>${records.slice(0,30).map((x,i)=>`<tr><td>${i+1}</td><td>${h(x.mode)}</td><td>${x.date}</td><td>${x.score}</td></tr>`).join('')}</tbody></table>${!records.length?'<div class="empty">Finish a draft to start ranking.</div>':''}</div><div class="pane"><h3>Daily challenge.</h3>${days.length?days.map(r=>`<div class="summary-stat"><span>${r.date}</span><strong>${r.score}</strong></div>`).join(''):'<div class="empty">No daily scores yet.</div>'}<p class="notice">These are local personal records. A static GitHub Pages website cannot have real worldwide leaderboards or online friend leagues without an external backend.</p></div></div>`;
 else if(profileTab==='badges')body=`<div class="badge-grid">${badges.map(b=>`<div class="badge-tile ${app.medals[b.id]?'':'locked'}"><div class="emoji">${b.icon}</div><strong>${b.name} ${app.medals[b.id]?'✓':'🔒'}</strong><p class="mini-note">${b.desc}</p></div>`).join('')}</div>`;
 else if(profileTab==='hall'){let chosen=hist.flatMap(x=>x.picks||[]).sort((a,b)=>b.value-a.value);let r=hist.slice().sort((a,b)=>a.score-b.score);body=`<div class="two-col"><div class="pane"><h3>Hall of fame.</h3>${career?.trophies?.length?career.trophies.map(x=>`<div class="summary-stat"><span>${x.year} · ${x.wins}–${x.losses}</span><b>${h(x.awards.join(', ')||'PRO SEASON')}</b></div>`).join(''):'<p class="muted">Complete a pro season to unlock trophies.</p>'}<div class="divline"></div><h3>Player records.</h3>${chosen.slice(0,10).map(x=>`<div class="summary-stat"><span>${h(x.name)} · ${h(x.slot)}</span><strong>${x.value}</strong></div>`).join('')||'<p class="muted">No player records yet.</p>'}</div><div class="pane"><h3>Hall of shame.</h3><p class="mini-note">Every legend has a rough night. Your lowest scores are displayed here too.</p>${r.slice(0,10).map(x=>`<div class="summary-stat"><span>${h(x.mode)} · ${x.date}</span><strong>${x.score}</strong></div>`).join('')||'<p class="muted">No draft results yet.</p>'}<div class="divline"></div><h3>100 Club.</h3><p>${hist.filter(x=>x.score>=99.5).length} perfect builds so far.</p></div></div>`}
 else if(profileTab==='league'){let names=app.localLeague||[];body=`<div class="two-col"><div class="pane"><h3>Local friend league.</h3><p>Keep a named league for people sharing this device. Add friends' names and compare scores entered on this device. No real online invite codes or remote syncing yet.</p><label class="field">ADD MEMBER NAME<input id="leagueName" maxlength="25" placeholder="Add a friend"></label><div class="action-row"><button class="btn green" id="addLeague">ADD MEMBER</button></div><div class="divline"></div>${names.map((n,i)=>`<div class="summary-stat"><span>${h(n)}</span><button class="btn sm" data-remove-league="${i}">REMOVE</button></div>`).join('')||'<div class="empty">League has no members yet.</div>'}</div><div class="pane"><h3>Local league leaderboard.</h3><p class="mini-note">Your saved drafts appear here. Other members can enter a score on the same browser.</p>${(app.leagueScores||[]).sort((a,b)=>b.score-a.score).map(x=>`<div class="summary-stat"><span>${h(x.name)}</span><strong>${x.score}</strong></div>`).join('')||'<p class="muted">No member scores yet.</p>'}<div class="divline"></div><label class="field">MEMBER<select id="leagueMember">${[app.username,...names].map(n=>`<option>${h(n)}</option>`).join('')}</select></label><label class="field" style="margin:10px 0">SCORE<input type="number" id="leagueScore" min="0" max="100" step="0.1"></label><button class="btn green" id="submitLeagueScore">SAVE LOCAL SCORE</button></div></div>`}
 else if(profileTab==='past'){let entries=Array.from({length:7},(_,i)=>{let d=new Date(Date.now()-(i+1)*86400000);return d.toISOString().slice(0,10)});body=`<div class="pane"><h3>Past daily practice.</h3><p>Replay any previous day's deterministic board. Practice results don't count toward today's daily challenge.</p><div class="selection-row">${entries.map(date=>`<button data-past-day="${date}">${date} · PRACTICE</button>`).join('')}</div></div>`}
 else body=`<div class="two-col"><div class="pane"><h3>Profile settings.</h3><label class="field">LOCAL DISPLAY NAME<input id="usernameInput" maxlength="25" value="${h(app.username)}"></label><button class="btn green" style="margin-top:10px" id="saveUsername">SAVE NAME</button><div class="divline"></div><button class="btn" id="toggleTheme">${app.theme==='dark'?'USE LIGHT THEME':'USE DARK THEME'}</button><p class="notice">All game saves are kept locally in your browser. Clear browser storage and you could lose them.</p></div><div class="pane"><h3>Your game data.</h3><p>Export a backup, or restore from an earlier backup on your computer. This doesn't upload your data anywhere.</p><div class="action-row"><button class="btn green" id="exportSave">EXPORT SAVE ↓</button><label class="btn" style="cursor:pointer">IMPORT SAVE ↑<input id="importSave" type="file" accept="application/json" hidden></label></div><div class="divline"></div><button class="btn primary" id="resetStorage">RESET ALL LOCAL DATA</button></div></div>`;
 return `<div class="page-title"><div><div class="eyebrow">PERSONAL SPORTS ARCHIVE · LOCAL DATA</div><h1>Your trophy room.</h1><p>${h(app.username)} · ${sp().name} · stats, badges, drafts, and history.</p></div></div><div class="selection-row" style="margin-bottom:16px">${tabs.map(([id,txt])=>`<button data-profile-tab="${id}" class="${profileTab===id?'active':''}">${txt}</button>`).join('')}</div>${body}`}
function startPastDaily(date){newDraft('blind');let d=app.draft;d.mode='practice';d.seed=hash(date+':'+app.sport+':daily');d.date=date;d.picks=[];d.round=0;d.rollIndex=0;d.categories=null;rollDraft(d);persist();render();}
function render(){headerRender();const page=app.page;$('#page').innerHTML=page==='home'?renderHome():page==='draft'?renderDraft():page==='career'?renderCareer():page==='coach'?renderCoach():page==='grid'?renderGrid():renderProfile();if(page==='coach'&&coach)drawCoachCanvas(performance.now()/1000);}
function applyDecision(action,e){const d=app.draft;let c=owned();
 if(action==='brandHome'){setPage('home');return}
 if(action==='themeBtn'||action==='toggleTheme'){app.theme=app.theme==='dark'?'light':'dark';saveAndRender();return}
 if(action==='menuToggle'){$('#navTop').classList.toggle('mobile-open');return}
 if(action==='openAbout'){modal(`<h2>About ERA RIVALS</h2><p>An original independent four-sport, pro-only fantasy game, inspired by the category of historical sports draft puzzles. It contains original simulation logic, 2D tactical play and curated player-season references.</p><p><b>What is real:</b> Athlete names, teams and historical season labels from a limited reference collection. <b>What is fictional:</b> All fantasy game ratings, box-score-like values, match results, championship histories and simulated career offers.</p><p>Daily challenges are deterministic by date and sport. Data saves in your browser. Public sign-in, global leaderboards, remote friend leagues, official real box scores and licensing deals are <b>not</b> built in.</p><p>Single player only. Professional careers only. Previous versions of ERA RIVALS remain in the navigation.</p><button class="btn green" id="cancelModal">CLOSE</button>`);return}
 if(action==='cancelModal'){closeModal();return}
 if(action==='leaveDraft'){resetDraft();return}
 if(action==='saveBuildFromDraft'){if(!d?.done)return;let name=app.username+' · '+d.sport.toUpperCase()+' '+d.total;app.builds.unshift({name,score:d.total,sport:d.sport,created:today(),picks:d.picks});app.builds=app.builds.slice(0,75);persist();notify('Build saved to your trophy room');return}
 if(action==='restartSameMode'){newDraft(d.mode==='practice'?'blind':d.mode);return}
 if(action==='dailyCareer'){resetCareerSetup(app.sport);careerSetup.era=[1984,1992,2003,2016,2026][seeded(today()+app.sport,0,4)];careerSetup.team=PRO_TEAMS[app.sport][seeded(today()+app.sport+':team',0,PRO_TEAMS[app.sport].length-1)];careerSetup.name='Daily Prospect';showCareerCreator=true;app.page='career';render();notify('Daily scenario loaded');return}
 if(action==='createCareer'){careerSetup.name=$('#createName')?.value.trim()||careerSetup.name;careerSetup.customTeam=$('#createCustomTeam')?.value||careerSetup.customTeam||'';careerSetup.team=$('#createTeam')?.value||careerSetup.team;careerSetup.number=clamp(Number($('#createNumber')?.value)||9,0,99);careerSetup.era=Number($('#createEra')?.value)||2026;careerSetup.pos=$('#createPos')?.value||careerSetup.pos;showCareerCreator=false;createCareer();return}
 if(action==='newCareer'){newCareerConfirm();return}
 if(action==='replaceCareerNow'){if(app.careers)delete app.careers[app.sport];if(app.career?.sport===app.sport)app.career=null;closeModal();resetCareerSetup(app.sport);showCareerCreator=true;render();return}
 if(action==='nextSeason'){nextCareerSeason();return}
 if(action==='trainCareer'){trainCareer();return}
 if(action==='scoutProspects'){scoutDialog();return}
 if(action==='transferCareer'){transferDialog();return}
 if(action==='acceptTransfer'){let to=$('#transferTo')?.value;if(c&&to){c.team=to;c.roster=rosterFor(c.sport,c.year,c.team,c.player);c.history.unshift(`Transferred to ${to} for a new professional challenge.`);c.contract=3;persist();closeModal();render();notify('Transfer completed.')}return}
 if(action==='newCoach'){initCoach(false);return}
 if(action==='startCareerMatch'){if(!c){setPage('career');notify('Create a pro career first');return}initCoach(true);return}
 if(action==='coachPause'){coachPause();return}
 if(action==='coachStep'){coachStep();return}
 if(action==='coachFinish'){coachSimFinal();return}
 if(action==='coachTimeout'){coachTimeout();return}
 if(action==='callPlay'){if(coach){coach.nextPlay=$('#playSelect')?.value||coach.nextPlay;coachLog(`Coach calls ${coach.nextPlay} for the next play.`);persist();render();notify('Play called');}return}
 if(action==='drawRoute'){if(coach){coach.drawing=!coach.drawing;if(!coach.drawing&&coach.customPath.length<2)coach.customPath=[];render();}return}
 if(action==='applyTactic'){if(coach){coach.tactic=$('#tacticSelect')?.value||coach.tactic;coachLog(`Strategy changed to ${coach.tactic}.`);render();notify('Tactics applied');}return}
 if(action==='queueSub'){if(coach){if(!coach.bench.length)return;coach.pendingSub={out:Number($('#subOut')?.value),inIndex:Number($('#subIn')?.value)};coachLog('Substitution queued for the next stoppage.');render();notify('Sub queued');}return}
 if(action==='submitGrid'){gridGuess($('#gridInput')?.value||'');return}
 if(action==='gridHelp'){modal('<h2>Nine squares</h2><p>Choose a square. Enter the name of a player in our curated player-season database whose playing position matches the row and whose season/rating matches the column. Nine total guesses and no repeated names. Original puzzle design and local daily progress.</p><button class="btn green" id="cancelModal">GOT IT</button>');return}
 if(action==='editUsername'){profileTab='settings';render();return}
 if(action==='saveUsername'){app.username=($('#usernameInput')?.value||'Coach').trim().slice(0,25)||'Coach';saveAndRender();notify('Name saved');return}
 if(action==='addLeague'){let v=($('#leagueName')?.value||'').trim().slice(0,25);if(v&&!(app.localLeague||[]).includes(v)){app.localLeague=app.localLeague||[];app.localLeague.push(v);saveAndRender()}return}
 if(action==='submitLeagueScore'){let name=$('#leagueMember')?.value||app.username,score=Number($('#leagueScore')?.value);if(!Number.isFinite(score)||score<0||score>100){notify('Score must be from 0 to 100');return}app.leagueScores=app.leagueScores||[];app.leagueScores.push({name,score,date:today()});app.leagueScores=app.leagueScores.slice(-100);saveAndRender();return}
 if(action==='exportSave'){const blob=new Blob([JSON.stringify({...app,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='era-rivals-pro-lab-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);notify('Save exported');return}
 if(action==='resetStorage'){modal('<h2>Reset local ERA RIVALS progress?</h2><p>This removes saved careers, drafts, badges, and local records from this browser. Export a backup first if you want to keep them.</p><div class="action-row"><button class="btn primary" id="resetConfirmed">DELETE LOCAL PROGRESS</button><button class="btn" id="cancelModal">CANCEL</button></div>');return}
 if(action==='resetConfirmed'){app=baseSave();coach=null;closeModal();persist();render();notify('Local progress reset');return}
}
document.addEventListener('click',e=>{
 const button=e.target.closest('button,a');if(!button)return;
 if(button.dataset.sport){selectSport(button.dataset.sport);return}
 if(button.dataset.page){setPage(button.dataset.page);return}
 if(button.dataset.mode){newDraft(button.dataset.mode);return}
 if(button.dataset.pick){pickDraft(button.dataset.pick);return}
 if(button.dataset.reroll){rerollDraft(button.dataset.reroll);return}
 if(button.dataset.budget){changeAuction(button.dataset.budget);return}
 if(button.dataset.track){careerSetup.track=button.dataset.track;render();return}if(button.dataset.buildPos){resetCareerSetup(app.sport);careerSetup.pos=button.dataset.buildPos;careerSetup.height=WIDTHS[app.sport]?.[careerSetup.pos]||careerSetup.height;showCareerCreator=true;setPage('career');return}
 if(button.dataset.coachTab){coachTab=button.dataset.coachTab;render();return}
 if(button.dataset.speed){if(coach){coach.speed=Number(button.dataset.speed);render();}return}
 if(button.dataset.simGames){simCareerGames(Number(button.dataset.simGames));return}
 if(button.dataset.gridCell){gridSelected=Number(button.dataset.gridCell);render();return}
 if(button.dataset.profileTab){profileTab=button.dataset.profileTab;render();return}
 if(button.dataset.sign){signProspect(button.dataset.sign);return}
 if(button.dataset.removeLeague){app.localLeague.splice(Number(button.dataset.removeLeague),1);saveAndRender();return}
 if(button.dataset.pastDay){startPastDaily(button.dataset.pastDay);return}
 if(button.id){applyDecision(button.id,e);}
});
document.addEventListener('change',e=>{let t=e.target;if(t.id==='teamLock'){changeTeamMode(t.value);return}if(t.id==='createPos'){careerSetup.pos=t.value;careerSetup.height=WIDTHS[app.sport]?.[t.value]||careerSetup.height;render();return}if(t.id==='createEra'){careerSetup.era=Number(t.value);return}if(t.id==='createTeam'){careerSetup.team=t.value;return}if(t.id==='createName'){careerSetup.name=t.value;return}if(t.id==='createCustomTeam'){careerSetup.customTeam=t.value;return}if(t.id==='createNumber'){careerSetup.number=Number(t.value);return}if(t.id==='createHeight'){careerSetup.height=Number(t.value);render();return}if(t.id==='createWeight'){careerSetup.weight=Number(t.value);render();return}if(t.dataset.creatorSkill){changeCareerSkill(t.dataset.creatorSkill,t.value);return}
 if(t.id==='importSave'){let file=t.files?.[0];if(file)file.text().then(txt=>{let v=JSON.parse(txt);if(!v||typeof v!=='object'||!LEAGUES[v.sport])throw Error('Invalid save');app={...baseSave(),...v,page:'home'};coach=null;persist();render();notify('Backup imported')}).catch(()=>notify('Could not import save'));return}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Enter'&&e.target.id==='gridInput'){e.preventDefault();gridGuess($('#gridInput')?.value||'')}});
document.addEventListener('click',e=>{const canvas=e.target.closest('#simCanvas');if(!canvas||!coach)return;const r=canvas.getBoundingClientRect(),x=clamp((e.clientX-r.left)/r.width,0,1),y=clamp((e.clientY-r.top)/r.height,0,1);if(coach.drawing){coach.customPath.push([x,y]);if(coach.customPath.length>8)coach.customPath.shift();notify('Route point added');drawCoachCanvas(performance.now()/1000);return;}let p=[...coach.homeActors,...coach.awayActors].map(z=>({...z,dist:Math.hypot(z.x-x,z.y-y)})).sort((a,b)=>a.dist-b.dist)[0];if(p&&p.dist<.10)notify(`${p.name} · ${p.pos} · ${p.rating} OVR · ${Math.round(p.energy)}% energy`);});
// Initialize: restore only ordinary state; an unfinished coach match is deliberately not persisted.
if(!window._ER_RIVALS_ACTIVE){window._ER_RIVALS_ACTIVE=true;render();coachRAF=requestAnimationFrame(animateCoach);}